301	    /**
302	     * Remembers the owner just created under its request's {@code Idempotency-Key}, so a later create
303	     * repeating that key is served the same owner ({@link #replayIdempotentCreate}). A {@code null} or
304	     * blank key is ignored, leaving that create non-idempotent.
305	     *
306	     * @param idempotencyKey the {@code Idempotency-Key} header value, or {@code null} if absent
307	     * @param ownerId        the id of the owner that was just created
308	     */
309	    private void rememberIdempotentCreate(String idempotencyKey, Integer ownerId) {
310	        if (!isBlank(idempotencyKey)) {
311	            idempotentCreateOwnerIds.put(idempotencyKey, ownerId);
312	        }
313	    }
