504	    /**
505	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
506	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
507	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
508	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
509	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
510	     *
511	     * @param telephone the raw telephone value submitted by the client
512	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
513	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
514	     *                                     400 response
515	     */
516	    private String normalizeTelephone(String telephone) {
517	        String e164 = toE164(telephone);
518	        if (e164 == null) {
519	            throw new InvalidOwnerFieldsException(List.of("telephone"));
520	        }
521	        return e164;
522	    }
523	
524	    /**
525	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
526	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
527	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
528	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits,
529	     * and when the supplied country code is one with a known national-number length
530	     * ({@link #NATIONAL_NUMBER_LENGTHS}, e.g. {@code '+61'} => 9, {@code '+1'} => 10) the national
531	     * number must have exactly that many digits.
532	     *
533	     * @param telephone the raw telephone value, possibly {@code null}
534	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
535	     */
536	    private String toE164(String telephone) {
537	        if (telephone == null) {
538	            return null;
539	        }
540	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
541	        boolean hasPlus = cleaned.startsWith("+");
542	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
543	        String nationalSignificant = hasPlus
544	            ? digits
545	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
546	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
547	            return null;
548	        }
549	        if (!hasValidNationalNumberLength(nationalSignificant)) {
550	            return null;
551	        }
552	        return "+" + nationalSignificant;
553	    }
554	
555	    /**
556	     * Checks the national-number length of an E.164 number (country code plus national significant
557	     * digits, no leading {@code '+'}) against the per-country requirement in
558	     * {@link #NATIONAL_NUMBER_LENGTHS}. The longest listed country code that prefixes the number
559	     * selects the requirement, and the remaining digits must number exactly that many. A number whose
560	     * country code is not listed carries no per-country length requirement and is accepted.
561	     *
562	     * @param nationalSignificant the digits of the E.164 number, country code first, without the
563	     *                            leading {@code '+'}
564	     * @return {@code true} if the national-number length is correct for the country code, or the
565	     *         country code has no listed requirement; {@code false} otherwise
566	     */
567	    private boolean hasValidNationalNumberLength(String nationalSignificant) {
568	        String countryCode = NATIONAL_NUMBER_LENGTHS.keySet().stream()
569	            .filter(nationalSignificant::startsWith)
570	            .max(Comparator.comparingInt(String::length))
571	            .orElse(null);
572	        if (countryCode == null) {
573	            return true;
574	        }
575	        int nationalLength = nationalSignificant.length() - countryCode.length();
576	        return nationalLength == NATIONAL_NUMBER_LENGTHS.get(countryCode);
577	    }
